107	      "XLA_CPU_JIT", patterns, context, converter, /*prefer_tf2xla=*/false);
108	  stablehlo::StablehloToHloTypeConverter hlo_converter;
109	  chlo::populateChloToHloPatterns(context, &hlo_converter, &patterns);
110	  chlo::ConstantLikeOp::getCanonicalizationPatterns(patterns, context);
111	
112	  ConversionTarget target(*context);
113	  target.addIllegalDialect<chlo::ChloDialect>();
114	  target.addLegalDialect<mhlo::MhloDialect>();
115	  target.addLegalDialect<arith::ArithDialect>();
116	  target.addLegalDialect<func::FuncDialect>();
117	  target.addLegalDialect<tensor::TensorDialect>();
118	  target.addLegalDialect<shape::ShapeDialect>();
119	  target.addLegalOp<func::CallOp>();
